<script setup>
import {printDocument} from "./printing.js";
import {ref, computed, onBeforeUnmount} from 'vue';
import {showSectionGenerator} from './section-generator.js';
import ChantierAutocomplete from './ChantierAutocomplete.vue';
import CommercialExtrasPanel from './CommercialExtrasPanel.vue';
const frappe = window.frappe;
const api='mat_reco.material_reconfiguration.services.chantier_service.';
const data=ref({chantiers:[],sections:[],quotations:[],lines:[],summary:{}}), selected=ref(''), section=ref(''), busy=ref(false), error=ref('');
const dirty=ref(false), chosen=ref({}), quoteKey=ref(null),assignmentTargets=ref([]),expandedArticles=ref({});
const visibleTargets=computed(()=>assignmentTargets.value.filter(id=>macroLines.value.some(l=>l.line_id===id)));
function toggleAllTargets(){const visible=macroLines.value.map(l=>l.line_id);assignmentTargets.value=visible.every(id=>assignmentTargets.value.includes(id))?assignmentTargets.value.filter(id=>!visible.includes(id)):[...new Set([...assignmentTargets.value,...visible])];}
function applyExtras(rows){if(!rows.length)return;data.value.chantier.commercial_extras||=[];data.value.chantier.commercial_extras.push(...rows);dirty.value=true;}
async function beforeBatch(){return !dirty.value||await saveMacro();}
const technicalApi='mat_reco.material_reconfiguration.services.technical_study_service.';
let serial=0, timer=null;
async function call(method,args={}) { return (await frappe.call({method:api+method,args,type:method==='get_dossier'?'GET':'POST'})).message; }
function describe(e) { try{return JSON.parse(JSON.parse(e._server_messages)[0]).message;}catch{return e.message||'Impossible de charger le dossier.';} }
async function refresh() {
 const request=++serial; busy.value=true;error.value='';
 try {const result=await call('get_dossier',{chantier:selected.value||null});if(request===serial){data.value=result;dirty.value=false;chosen.value={};for(const row of result.chantier?.lines||[]){const remaining=Math.max(0,row.qty-(result.quote_usage?.[row.line_id]||0));chosen.value[row.line_id]={selected:remaining>0,qty:remaining};}}}
 catch(e){if(request===serial)error.value=describe(e);} finally{if(request===serial)busy.value=false;}
}
function choose(){section.value='';assignmentTargets.value=[];refresh();}
const scope=computed(()=>{const names=new Set(section.value?[section.value]:[]);let changed=true;while(changed){changed=false;for(const s of data.value.sections)if(names.has(s.parent_chantier_section)&&!names.has(s.name)){names.add(s.name);changed=true;}}return names;});
const macroLines=computed(()=>(data.value.chantier?.lines||[]).filter(l=>!section.value||scope.value.has(l.section)));
const commercialDraft=computed(()=>data.value.chantier?.docstatus===0&&data.value.chantier?.status!=='Cancelled'&&data.value.permissions?.write);
const readyForQuote=computed(()=>data.value.chantier?.docstatus===1&&data.value.technical?.docstatus===1&&!data.value.technical_stale);
const techLine=(id)=>data.value.technical?.lines?.find(l=>l.line_id===id);
const effectiveUom=(row)=>row.uom||JSON.parse(techLine(row.line_id)?.tree_json||'{}').stock_uom||'Unité à définir';
const lines=computed(()=>data.value.lines.filter(l=>!section.value||scope.value.has(l.section)));
const summary=computed(()=>section.value?(data.value.by_section?.[section.value]||{}):data.value.summary);
const depth=(node)=>{let n=0,seen=new Set();while(node?.parent_chantier_section&&!seen.has(node.name)){seen.add(node.name);n++;node=data.value.sections.find(s=>s.name===node.parent_chantier_section);}return n;};
const stateName=(value)=>({completed:'Terminée',ready:'Réalisable',partial:'Partiellement réalisable',blocked:'Bloquée',ok:'Besoin satisfait',Preparation:'Préparation',Quotation:'Chiffrage',Confirmed:'Confirmé','In Production':'En fabrication',Completed:'Terminé','On Hold':'Suspendu',Cancelled:'Annulé'})[value]||value;
const sectionName=(name)=>data.value.sections.find(s=>s.name===name)?.section_name||'Sans section';
const fmt=(n)=>Number(n||0).toLocaleString('fr-FR',{maximumFractionDigits:2});
function open(dt,name){frappe.set_route('Form',dt,name);}
function form(title,fields,onSave) {const dialog=new frappe.ui.Dialog({title,fields,primary_action_label:'Enregistrer',async primary_action(values){dialog.disable_primary_action();try{await onSave(values);dialog.hide();await refresh();}catch(e){frappe.msgprint(describe(e));}finally{dialog.enable_primary_action();}}});dialog.show();}
function newChantier(){form('Nouveau chantier',[
 {fieldname:'reference',label:'Référence',fieldtype:'Data',read_only:1,description:'Numéro automatique attribué à l’enregistrement (YYCHANTMM#####).'},{fieldname:'designation',label:'Désignation',fieldtype:'Data',reqd:1},
 {fieldname:'company',label:'Société',fieldtype:'Link',options:'Company',reqd:1,default:frappe.defaults.get_user_default('Company')},
 {fieldname:'customer',label:'Client',fieldtype:'Link',options:'Customer',reqd:1},{fieldname:'responsible',label:'Responsable',fieldtype:'Link',options:'User',default:frappe.session.user},
 {fieldname:'expected_start_date',label:'Début prévu',fieldtype:'Date'},{fieldname:'expected_end_date',label:'Fin de fabrication prévue',fieldtype:'Date'}
 ],async(values)=>{const result=await frappe.call({method:'frappe.client.insert',args:{doc:{doctype:'Chantier',...values}}});selected.value=result.message.name;section.value='';});}
const templateApi='mat_reco.material_reconfiguration.services.chantier_templates.';
function saveSectionTemplate(){form('Enregistrer les sections comme modèle',[
 {fieldname:'template_name',label:'Nom du modèle',fieldtype:'Data',reqd:1}
 ],async(values)=>{const result=await frappe.call({method:templateApi+'save_template',args:{chantier:selected.value,...values}});frappe.show_alert({message:'Modèle enregistré : '+result.message,indicator:'green'});});}
function importSections(){form('Récupérer une arborescence de sections',[
 {fieldname:'source_type',label:'Source',fieldtype:'Select',options:'Modèle\nAutre chantier',default:'Modèle',reqd:1},
 {fieldname:'template',label:'Modèle',fieldtype:'Link',options:'Chantier Section Template',depends_on:'eval:doc.source_type === "Modèle"',mandatory_depends_on:'eval:doc.source_type === "Modèle"'},
 {fieldname:'source_chantier',label:'Chantier source',fieldtype:'Link',options:'Chantier',depends_on:'eval:doc.source_type === "Autre chantier"',mandatory_depends_on:'eval:doc.source_type === "Autre chantier"',get_query:()=>({filters:{name:['!=',selected.value]}})},
 {fieldtype:'HTML',fieldname:'explanation',options:'<p>Les sections et sous-sections seront ajoutées au chantier, dans leur ordre d’origine. Les sections existantes sont conservées. Aucun ouvrage ne sera copié.</p>'}
 ],async(values)=>{const result=await frappe.call({method:templateApi+'apply_sections',args:{chantier:selected.value,...(values.source_type==='Modèle'?{template:values.template}:{source_chantier:values.source_chantier})}});section.value='';frappe.show_alert({message:result.message.count+' section(s) ajoutée(s)',indicator:'green'});});}
function generateSections(){showSectionGenerator(selected.value,async()=>{section.value='';await refresh();},describe);}
function newSection(){form('Nouvelle section',[
 {fieldname:'section_name',label:'Désignation',fieldtype:'Data',reqd:1},
 {fieldname:'parent_chantier_section',label:'Section parente (facultatif)',fieldtype:'Link',options:'Chantier Section',default:section.value||undefined,get_query:()=>({filters:{chantier:selected.value,is_group:1}})}
 ],async(values)=>{await frappe.call({method:'frappe.client.insert',args:{doc:{doctype:'Chantier Section',chantier:selected.value,is_group:1,...values}}});});}
async function tcall(method,args={},write=true){return(await frappe.call({method:technicalApi+method,args,type:write?'POST':'GET'})).message;}
async function saveMacro(){busy.value=true;error.value='';try{await tcall('save_commercial',{chantier:selected.value,modified:data.value.chantier.modified,lines:JSON.stringify(data.value.chantier.lines),commercial_extras:JSON.stringify(data.value.chantier.commercial_extras||[]),currency:data.value.chantier.currency,selling_price_list:data.value.chantier.selling_price_list,terms:data.value.chantier.terms});await refresh();return true;}catch(e){error.value=describe(e);return false;}finally{busy.value=false;}}
function nextRepere(){const used=new Set(data.value.chantier.lines.map(l=>l.repere));let n=1;while(used.has('OUV-'+String(n).padStart(3,'0')))n++;return 'OUV-'+String(n).padStart(3,'0');}
function editMacro(row=null){const defaults=row||{repere:nextRepere(),designation:'',section:section.value,qty:1,uom:'PC',rate:0,rate_set:0};const fields=[
 {fieldname:'designation',label:'Désignation de l’ouvrage',fieldtype:'Autocomplete',ignore_validation:1,max_items:10,reqd:1},
 {fieldname:'section',label:'Section',fieldtype:'Link',options:'Chantier Section',get_query:()=>({filters:{chantier:selected.value}})},
 {fieldname:'proposed_item',label:'Item existant (facultatif)',fieldtype:'Link',options:'Item',get_query:()=>({filters:{custom_item_types:['in',['OUVRAGE','DECOUPE']],has_serial_no:1,disabled:0}})},
 {fieldname:'length_mm',label:'Longueur connue (mm)',fieldtype:'Float'},{fieldname:'width_mm',label:'Hauteur connue (mm)',fieldtype:'Float'},{fieldname:'thickness_mm',label:'Épaisseur connue (mm)',fieldtype:'Float'},
 {fieldname:'qty',label:'Quantité',fieldtype:'Int',reqd:1},{fieldname:'uom',label:'Unité du prix',fieldtype:'Link',options:'UOM'},
 {fieldname:'rate',label:'Prix unitaire proposé',fieldtype:'Currency'},{fieldname:'rate_set',label:'Prix confirmé (facultatif)',fieldtype:'Check'}
 ].map(f=>({...f,default:defaults[f.fieldname]}));
 const dialog=new frappe.ui.Dialog({title:row?'Modifier l’ouvrage':'Ajouter un ouvrage commercial',fields,primary_action_label:'Appliquer',primary_action(v){if(row)Object.assign(row,v);else data.value.chantier.lines.push({...v,repere:nextRepere(),line_id:globalThis.crypto?.randomUUID?.()||'line-'+Date.now()+'-'+Math.random().toString(16).slice(2)});dirty.value=true;dialog.hide();}});dialog.show();
 const control=dialog.fields_dict.designation;let request=0;
 async function suggest(){const current=++request,txt=control.$input.val()||'';try{const values=await tcall('designation_suggestions',{txt},false);if(current===request){control.set_data(values.map(value=>({value,label:frappe.utils.escape_html(value)})));control.awesomplete.evaluate();}}catch(e){if(current===request)control.set_data([]);}}
 control.$input.on('input.designations focus.designations',frappe.utils.debounce(suggest,180));
}
const extrasFor=(id)=>(data.value.chantier.commercial_extras||[]).filter(e=>e.parent_line_id===id);
async function editExtra(parent,row=null){
 if(dirty.value&&!(await saveMacro()))return;
 parent=data.value.chantier.lines.find(l=>l.line_id===parent.line_id);
 if(row)row=data.value.chantier.commercial_extras.find(e=>e.line_id===row.line_id);
 let preview=null,request=0;
 async function updateItem(){
  const code=dialog.get_value('item_code'),current=++request;if(!code)return;
  dialog.disable_primary_action();
  try{
   const value=(await frappe.call({method:'mat_reco.material_reconfiguration.services.chantier_extras.preview',args:{chantier:selected.value,parent_line_id:parent.line_id,item_code:code}})).message;
   if(current!==request)return;preview=value;
   await dialog.set_values({manual_qty:value.manual_qty,qty:value.qty,rate:value.found?value.rate:0,rate_set:value.found?1:0,basis:value.calculation_basis+' · quantité calculée : '+fmt(value.calculated_qty)+' '+value.uom});
   toggleQuantity();
  }catch(e){preview=null;frappe.msgprint(describe(e));}finally{if(current===request)dialog.enable_primary_action();}
 }
 function toggleQuantity(){dialog.set_df_property('qty','read_only',!dialog.get_value('manual_qty'));if(preview&&!dialog.get_value('manual_qty'))dialog.set_value('qty',preview.calculated_qty);}
 const dialog=new frappe.ui.Dialog({title:'Services / Accessoires — '+parent.designation,fields:[
  {fieldname:'item_code',label:'Service ou accessoire',fieldtype:'Link',options:'Item',reqd:1,default:row?.item_code,get_query:()=>({filters:{custom_item_types:['in',['SERVICE','ACCESSOIRE']],disabled:0,is_sales_item:1}}),onchange:updateItem},
  {fieldname:'basis',label:'Base de calcul',fieldtype:'Data',read_only:1,default:row?.calculation_basis},
  {fieldname:'manual_qty',label:'Quantité manuelle / ajustée',fieldtype:'Check',default:row?.manual_qty||0,onchange:toggleQuantity},
  {fieldname:'qty',label:'Quantité totale pour cet ouvrage commercial',fieldtype:'Float',reqd:1,default:row?.qty||1},
  {fieldname:'rate',label:'Prix unitaire',fieldtype:'Currency',default:row?.rate||0},
  {fieldname:'rate_set',label:'Prix confirmé (facultatif)',fieldtype:'Check',default:row?.rate_set||0}
 ],primary_action_label:'Appliquer',primary_action(v){
  if(!preview&&v.item_code!==row?.item_code){frappe.msgprint('Sélectionner un service ou accessoire valide et attendre son chargement.');return;}
  const value={...v,...(preview?{item_name:preview.item_name,item_type:preview.item_type,uom:preview.uom,calculation_basis:preview.calculation_basis,calculated_qty:preview.calculated_qty}:{}),parent_line_id:parent.line_id};delete value.basis;
  if(!(Number(v.qty)>0)||Number(v.rate)<0){frappe.msgprint('Quantité positive et prix positif ou nul requis.');return;}
  if(row)Object.assign(row,value);else{data.value.chantier.commercial_extras||=[];data.value.chantier.commercial_extras.push({...value,line_id:globalThis.crypto?.randomUUID?.()||'extra-'+Date.now()+'-'+Math.random().toString(16).slice(2)});}
  dirty.value=true;dialog.hide();
 }});dialog.show();
}
function removeExtra(extra){frappe.confirm('Retirer ce service ou accessoire ?',()=>{data.value.chantier.commercial_extras=data.value.chantier.commercial_extras.filter(e=>e.line_id!==extra.line_id);dirty.value=true;});}
function removeMacro(row){frappe.confirm('Retirer cet ouvrage du brouillon commercial ?',()=>{data.value.chantier.lines=data.value.chantier.lines.filter(l=>l.line_id!==row.line_id);data.value.chantier.commercial_extras=(data.value.chantier.commercial_extras||[]).filter(e=>e.parent_line_id!==row.line_id);dirty.value=true;});}
async function price(row){const id=row.line_id;if(dirty.value){if(!(await saveMacro()))return;row=data.value.chantier.lines.find(l=>l.line_id===id);}busy.value=true;error.value='';try{const code=techLine(row.line_id)?.result_item||row.proposed_item;if(!code)throw new Error('Sélectionner un Item existant ou terminer l’étude pour rechercher son tarif.');const value=await tcall('get_rate',{chantier:selected.value,item_code:code,uom:row.uom},false);if(value.found){row.rate=value.rate;row.rate_set=1;row.price_source='Price List';dirty.value=true;}else frappe.msgprint('Aucun prix applicable : saisir et confirmer le prix proposé.');}catch(e){error.value=describe(e);}finally{busy.value=false;}}
async function technical(){if(dirty.value&&!(await saveMacro()))return;busy.value=true;error.value='';try{const name=await tcall('prepare_study',{chantier:selected.value});frappe.set_route('technical-study',name);}catch(e){error.value=describe(e);}finally{busy.value=false;}}
function viewTechnical(){frappe.set_route('technical-study',data.value.technical.name);}
function submitCommercial(){frappe.confirm('Valider les quantités, prix et conditions commerciales après l’étude technique ?',async()=>{if(dirty.value&&!(await saveMacro()))return;busy.value=true;error.value='';try{await frappe.call({method:'frappe.client.submit',args:{doc:data.value.chantier}});await refresh();}catch(e){error.value=describe(e);}finally{busy.value=false;}});}
function cancelChantier(){frappe.confirm('Annuler ce chantier ? Toutes les études et tous les devis doivent être supprimés ou annulés.',async()=>{busy.value=true;error.value='';try{await tcall('cancel_dossier',{chantier:selected.value,modified:data.value.chantier.modified});await refresh();}catch(e){error.value=describe(e);}finally{busy.value=false;}});}
async function newQuotation(){const selection=Object.entries(chosen.value).filter(([id,v])=>v.selected&&v.qty>0).map(([line_id,v])=>({line_id,qty:v.qty}));if(!selection.length){frappe.msgprint('Sélectionner au moins un ouvrage et sa quantité.');return;}const dialog=new frappe.ui.Dialog({title:'Générer le devis depuis le chantier approuvé',fields:[{fieldname:'submit',label:'Valider également le devis',fieldtype:'Check',default:1}],primary_action_label:'Générer',async primary_action(v){dialog.disable_primary_action();busy.value=true;error.value='';try{quoteKey.value||=globalThis.crypto?.randomUUID?.()||String(Date.now())+Math.random();const name=await tcall('generate_quotation',{chantier:selected.value,selections:JSON.stringify(selection),request_key:quoteKey.value,submit:v.submit});quoteKey.value=null;dialog.hide();open('Quotation',name);}catch(e){error.value=describe(e);}finally{dialog.enable_primary_action();busy.value=false;}}});dialog.show();}
function confirmOrder(quote){const dialog=new frappe.ui.Dialog({title:'Confirmer l’acceptation client',fields:[{fieldname:'acceptance',label:'Référence ou justificatif de l’accord client',fieldtype:'Data',reqd:1},{fieldname:'delivery_date',label:'Date prévue',fieldtype:'Date',reqd:1,default:frappe.datetime.add_days(frappe.datetime.get_today(),7)}],primary_action_label:'Créer et valider la commande',async primary_action(v){dialog.disable_primary_action();try{quoteKey.value||=globalThis.crypto?.randomUUID?.()||String(Date.now())+Math.random();const name=await tcall('confirm_order',{quotation:quote.name,acceptance_reference:v.acceptance,delivery_date:v.delivery_date,request_key:quoteKey.value});quoteKey.value=null;dialog.hide();open('Sales Order',name);}catch(e){frappe.msgprint(describe(e));}finally{dialog.enable_primary_action();}}});dialog.show();}
async function mpp(line){busy.value=true;error.value='';try{const name=await call('create_mpp',{sales_order:line.sales_order,sales_order_item:line.sales_order_item});open('Material Production Plan',name);}catch(e){error.value=describe(e);}finally{busy.value=false;}}
function workshop(){sessionStorage.setItem('univers-workshop-chantier',selected.value);frappe.set_route('workshop-cockpit');}
function show(){const stored=sessionStorage.getItem("univers-chantier-selected");if(stored){selected.value=stored;section.value="";sessionStorage.removeItem("univers-chantier-selected");}refresh();clearInterval(timer);timer=setInterval(()=>{if(!busy.value&&!dirty.value)refresh();},60000);}
function hide(){serial++;clearInterval(timer);timer=null;}
onBeforeUnmount(hide);defineExpose({show,hide});
</script>

<template>
<div class="ug-chantiers">
 <header><div><p>UNIVERS GLASS</p><h1>Chantiers</h1></div></header>
 <nav class="header-actions" aria-label="Actions du chantier">
 <button class="primary" :disabled="busy||!data.permissions?.chantier" @click="newChantier">+ Nouveau chantier</button>
 <button :disabled="busy" @click="refresh">{{busy?'Chargement…':'↻ Actualiser'}}</button>
 <template v-if="data.chantier?.name===selected">
 <button :disabled="busy||dirty" title="Enregistrer les modifications avant impression" @click="printDocument('Chantier',selected)">Imprimer A4</button>
 <button @click="open('Chantier',selected)">Modifier le dossier</button><button v-if="data.chantier.docstatus!==2&&data.chantier.status!=='Cancelled'&&(commercialDraft||data.permissions?.cancel)" :disabled="busy||dirty" @click="cancelChantier">Annuler le chantier</button>
 <template v-if="commercialDraft"><button :disabled="busy" @click="editMacro()">+ Ouvrage</button><button :disabled="dirty" @click="frappe.new_doc('Data Import',{reference_doctype:'Chantier',import_type:'Update Existing Records'})">Importer Excel</button><button class="primary" :disabled="busy||!dirty" @click="saveMacro">Enregistrer les ouvrages</button></template>
 <button v-if="data.technical" @click="viewTechnical">Voir l’étude technique</button><button v-if="commercialDraft&&(!data.technical||data.technical_stale)" :disabled="busy||!data.permissions?.technical" @click="technical">Préparer l’étude technique</button>
 <button v-if="commercialDraft&&data.permissions?.submit" :disabled="busy||data.technical?.docstatus!==1||data.technical_stale" @click="submitCommercial">Valider le commercial</button>
 <button :disabled="busy||!data.permissions?.quotation||!readyForQuote" @click="newQuotation">Générer un devis (sélection)</button>
 </template><button @click="selected?workshop():frappe.set_route('workshop-cockpit')">Atelier</button>
 </nav>
 <section class="toolbar selection-fields"><ChantierAutocomplete v-model="selected" :items="data.chantiers" :disabled="busy||dirty" @change="choose" /><template v-if="data.chantier?.name===selected"><label>Devise<input v-model="data.chantier.currency" :disabled="!commercialDraft" @input="dirty=true" /></label><label>Liste de prix<input v-model="data.chantier.selling_price_list" :disabled="!commercialDraft" placeholder="Facultative" @input="dirty=true" /></label></template></section>
 <div v-if="error" class="alert" role="alert" v-text="error"></div>
 <div v-if="!selected" class="empty">Sélectionnez un chantier ou créez un nouveau dossier.</div>
 <template v-else-if="data.chantier?.name===selected">
 <section class="dossier" :class="{cancelled:data.chantier.docstatus===2||data.chantier.status==='Cancelled'}"><h2>{{data.chantier.designation}}</h2><span>{{data.chantier.customer}} · {{data.chantier.status==='Cancelled'?'Annulé':['Brouillon commercial','Commercial validé','Annulé'][data.chantier.docstatus]}}</span></section>
 <div class="body" :class="{'with-extras':commercialDraft}"><section class="sections"><div class="heading"><h2>Sections</h2><button :disabled="busy || dirty || !data.permissions?.section || data.chantier.docstatus!==0" @click="newSection">+</button></div><button :class="{active:!section}" @click="section=''">Tout le chantier</button><button v-for="s in data.sections" :key="s.name" :class="{active:section===s.name}" :style="{paddingLeft:(12+depth(s)*16)+'px'}" @click="section=s.name">{{s.section_name}}</button><p v-if="!data.sections.length">Les sections sont facultatives.</p><button v-if="commercialDraft&&data.permissions?.section" :disabled="busy||dirty" @click="importSections">Récupérer des sections</button><button v-if="commercialDraft&&data.permissions?.section" :disabled="busy||dirty" @click="generateSections">Générer avec le LLM</button><button v-if="data.permissions?.section_template&&data.sections.length" :disabled="busy||dirty" @click="saveSectionTemplate">Enregistrer comme modèle</button><button v-if="section" @click="open('Chantier Section',section)">Modifier la section</button></section>
 <main>
 <section class="panel macro"><div class="heading"><h2>Articles</h2></div>
 <div v-if="data.technical_stale" class="alert">Les besoins ont changé depuis l’étude technique : une nouvelle validation technique est nécessaire.</div>
 <div v-if="commercialDraft" class="batch-targets"><button :disabled="busy||!macroLines.length" @click="toggleAllTargets">{{macroLines.length && macroLines.every(l=>assignmentTargets.includes(l.line_id))?'Désélectionner les ouvrages visibles':'Sélectionner les ouvrages visibles'}}</button><span>{{visibleTargets.length}} ouvrage(s) sélectionné(s) pour les services / accessoires</span></div><div class="table"><table><thead><tr><th>{{commercialDraft?'Affecter':'Au devis'}}</th><th>Article</th><th>Section</th><th>Dimensions techniques / proposées</th><th>Prévu</th><th>Prix unitaire</th><th>Actions</th></tr></thead><tbody><template v-for="row in macroLines" :key="row.line_id"><tr :class="{'assignment-selected':commercialDraft&&assignmentTargets.includes(row.line_id)}"><td><input v-if="commercialDraft" v-model="assignmentTargets" type="checkbox" :value="row.line_id" :disabled="busy" :aria-label="'Sélectionner l’ouvrage '+row.repere" /><input v-else-if="chosen[row.line_id]" v-model="chosen[row.line_id].selected" type="checkbox" :disabled="!readyForQuote" /><input v-if="readyForQuote&&chosen[row.line_id]" v-model.number="chosen[row.line_id].qty" type="number" min="0" :max="row.qty-(data.quote_usage?.[row.line_id]||0)" class="qty-input" /><small v-if="!commercialDraft">Déjà au devis : {{data.quote_usage?.[row.line_id]||0}}</small></td><td><div class="article-cell"><button class="article-toggle" :aria-expanded="!!expandedArticles[row.line_id]" :aria-controls="'extras-'+row.line_id" :aria-label="(expandedArticles[row.line_id]?'Replier ':'Déplier ')+row.designation" @click="expandedArticles[row.line_id]=!expandedArticles[row.line_id]">{{expandedArticles[row.line_id]?'▾':'▸'}}</button><span><strong>{{row.designation}}</strong><small>{{row.repere}}<template v-if="techLine(row.line_id)?.result_item||row.proposed_item"> · {{techLine(row.line_id)?.result_item||row.proposed_item}}</template></small></span></div></td><td>{{sectionName(row.section)}}</td><td>{{techLine(row.line_id)?.length_mm||row.length_mm||'—'}} × {{techLine(row.line_id)?.width_mm||row.width_mm||'—'}} × {{techLine(row.line_id)?.thickness_mm||row.thickness_mm||'—'}} mm</td><td>{{row.qty}} {{effectiveUom(row)}}</td><td>{{fmt(row.rate)}} {{data.chantier.currency}}<small>{{row.rate_set?'Prix confirmé':'Non confirmé'}}</small><button v-if="commercialDraft" :disabled="busy" @click="price(row)">Chercher le tarif</button></td><td><template v-if="commercialDraft"><button @click="editMacro(row)">Modifier</button><button :disabled="busy" @click="editExtra(row)">Services / Accessoires</button><button @click="removeMacro(row)">Retirer</button></template></td></tr><tr v-show="expandedArticles[row.line_id]" :id="'extras-'+row.line_id" class="ouvrage-extras"><td></td><td colspan="6"><details v-for="group in [{type:'SERVICE',label:'Services'},{type:'ACCESSOIRE',label:'Accessoires'}]" :key="group.type" class="extra-group"><summary>{{group.label}} <span>{{extrasFor(row.line_id).filter(e=>e.item_type===group.type).length}}</span></summary><ul><li v-for="extra in extrasFor(row.line_id).filter(e=>e.item_type===group.type)" :key="extra.line_id"><span class="extra-name">{{extra.item_name||extra.item_code}}</span><span>{{fmt(extra.qty)}} {{extra.uom}}</span><span>{{fmt(extra.rate)}} {{data.chantier.currency}}<small v-if="!extra.rate_set">Non confirmé</small></span><div v-if="commercialDraft" class="extra-actions"><button :disabled="busy" @click="editExtra(row,extra)">Modifier</button><button @click="removeExtra(extra)">Retirer</button></div></li><li v-if="!extrasFor(row.line_id).some(e=>e.item_type===group.type)" class="extra-empty">Aucun {{group.type==='SERVICE'?'service':'accessoire'}}</li></ul></details></td></tr></template><tr v-if="!macroLines.length"><td colspan="7">Ajouter les ouvrages dans cette section avant de préparer l’étude technique.</td></tr></tbody></table></div>
 <label class="terms">Conditions commerciales<textarea v-model="data.chantier.terms" :disabled="!commercialDraft" @input="dirty=true"></textarea></label>
 <p v-if="!readyForQuote">La génération du devis attend la validation technique puis la validation commerciale finale.</p>
 </section>
 <div v-if="data.production_visible===false" class="alert">Votre rôle permet de consulter le dossier et les devis. L’accès au suivi de fabrication nécessite le droit de lecture des mouvements de stock.</div>
 <template v-else>
 <section class="cards"><article><strong>{{fmt(summary.progress)}} %</strong><span>Surface conforme / commandée</span><progress :value="summary.progress||0" max="100"></progress><small>{{fmt(summary.conform_area)}} / {{fmt(summary.area)}} m²</small></article><article><strong>{{fmt(summary.ordered_qty)}}</strong><span>Pièces commandées</span><small>{{summary.ouvrages||0}} lignes d’ouvrages</small></article><article><strong>{{fmt(summary.remaining_qty)}}</strong><span>Pièces restant à fabriquer</span><small>{{summary.blocked||0}} lignes bloquées</small></article><article><strong>{{fmt(summary.pending_quality)}}</strong><span>En attente de qualité</span><small>Fabrications conformes : {{fmt(summary.produced_qty)}}</small></article></section>
 <section class="panel"><h2>Fabrication des commandes confirmées</h2><p>Les fabrications terminées restent incluses dans cette synthèse. Les refabrications ajoutent du travail sans augmenter la surface commerciale.</p><div class="table"><table><thead><tr><th>Repère / article</th><th>Section</th><th>Commande</th><th>Prévu</th><th>Conforme</th><th>Restant</th><th>Réalisable</th><th>État / plan</th></tr></thead><tbody><tr v-for="line in lines" :key="line.sales_order_item"><td><strong>{{line.repere}}</strong><small>{{line.item_code}}</small></td><td>{{sectionName(line.section)}}</td><td><button @click="open('Sales Order',line.sales_order)">{{line.sales_order}}</button></td><td>{{line.qty}}</td><td>{{line.produced}}</td><td>{{line.remaining}}<small v-if="line.refabrication">dont {{line.refabrication}} refabrication(s) demandée(s)</small></td><td>{{line.fabricable}}</td><td><small>{{stateName(line.state)}}</small><button :disabled="busy||['Closed','On Hold','Cancelled'].includes(line.status)" @click="line.mpp?open('Material Production Plan',line.mpp):mpp(line)">{{line.mpp?'Ouvrir MPP':'Préparer MPP'}}</button></td></tr><tr v-if="!lines.length"><td colspan="8">Aucune ligne de commande confirmée dans cette sélection.</td></tr></tbody></table></div></section>
 </template>
 <section class="panel"><h2>Devis et révisions</h2><p>Les devis reprennent la sélection des ouvrages et la définition technique approuvées. La commande nécessite l’acceptation du client.</p><div class="quotes"><button v-for="q in data.quotations" :key="q.name" @click="open('Quotation',q.name)"><strong>{{q.name}}</strong><span>{{q.status}} · {{fmt(q.grand_total)}} {{q.currency}}</span><small v-if="q.amended_from">Révision de {{q.amended_from}}</small></button><div v-for="q in data.quotations.filter(q=>q.docstatus===1)" :key="q.name+'-order'"><button @click="confirmOrder(q)">Créer une commande depuis {{q.name}}</button></div><p v-if="!data.quotations.length">Aucun devis pour ce chantier.</p></div></section>
 </main><CommercialExtrasPanel v-if="commercialDraft" :key="selected" :chantier="data.chantier" :parent-line-ids="visibleTargets" :disabled="busy" :before-apply="beforeBatch" @applied="applyExtras" /></div>
 </template>
</div>
</template>

